'use strict';
// Surplus arguments with side effects (corpus 13800): JS evaluates every
// argument left to right, then drops the surplus ones. Order is observable
// through the trace.
const trace = [];
function tick(tag) { trace.push(tag); return tag; }
function take() { const s = trace.join(','); trace.length = 0; return s; }

let counter = 1;
function bump() { counter = counter + 10; return 'bumped'; }

function add2(a, b) { return a + '+' + b; }
function Pair(a, b) { this.a = a; this.b = b; }
function none() { return 'none'; }
function zeroArity() { return none(tick('q')) + ' ' + take(); }

function fnSurplus() { return add2(tick('a'), tick('b'), tick('c'), tick('d')) + ' ' + take(); }
function ctorSurplus() {
  const p = new Pair(tick('x'), tick('y'), tick('z'));
  return p.a + '/' + p.b + ' ' + take();
}
function keptBeforeSurplus() {
  const r = add2(counter, bump());
  return r + ' ' + counter;
}
function ctorKeptBeforeSurplus() {
  const p = new Pair(counter, bump());
  return p.a + '/' + p.b + ' ' + counter;
}
function argumentsReader() {
  function sum() { return arguments.length + ':' + Array.prototype.join.call(arguments, ','); }
  return sum(tick('m'), tick('n'), tick('o')) + ' ' + take();
}

// mysql_clear_password shape (corpus 13801): a factory instantiated with `{}`
// reads an absent property inside `||` chains.
const create = (pluginOptions) => function plug({ connection, command }) {
  const password = command.password || pluginOptions.password || connection.config.password;
  return password;
};
const table = { clear: create({}), withPw: create({ password: 'opt' }) };
function clearPlain(cmd) { return table.clear({ connection: { config: { password: 'cfg' } }, command: cmd }); }
function clearOpt(cmd) { return table.withPw({ connection: { config: { password: 'cfg' } }, command: cmd }); }
function absentChain(o) { return (o.password || o.alt || 'none') + ':' + (o.password === undefined); }

module.exports = {
  zeroArity, fnSurplus, ctorSurplus, keptBeforeSurplus, ctorKeptBeforeSurplus,
  argumentsReader, clearPlain, clearOpt, absentChain,
};
